export const PROP_IDS = Object.freeze(Object.keys(PROPS));

// How much a scattered prop's size is allowed to wander, and how far it may be
// nudged off tile centre. Props all sitting dead centre on a 1 m grid is the
// same wallpaper problem the ground-wear pass hit with boot prints.
export const SCATTER_JITTER = Object.freeze({
  scale: [0.86, 1.18],
  offset: 0.28,
});

// Props that must NOT be rotated to a random yaw, because they have a right
// way up relative to the world rather than just to themselves.
export const FIXED_YAW = Object.freeze(new Set(['weather-vane']));
